import os, random, subprocess, glob, sys, time
seeds=[]
for root,dirs,files in os.walk('test'):
    for f in files:
        p=os.path.join(root,f)
        try:
            st=os.stat(p)
        except: continue
        if st.st_size<=100000 and (f.endswith(('.sam','.bam','.cram','.vcf','.bcf','.fq','.fai','.crai')) or '#' in f):
            seeds.append(open(p,'rb').read())
# add hand seeds
seeds += [b'CRAM\x03\x00' + b'\0'*100, b'BAM\1' + b'\0'*100, b'BCF\2\2' + b'\0'*100, b'@r\nA\n+\n!\n', b'##fileformat=VCFv4.2\n#CHROM\tPOS\tID\tREF\tALT\tQUAL\tFILTER\tINFO\n1\t1\t.\tA\tC\t.\t.\t.\n']
print('seeds',len(seeds))
random.seed(1)
start=time.time()
for i in range(20000):
    data=bytearray(random.choice(seeds))
    # random truncate/extend/mutate
    if random.random()<.3 and data:
        del data[random.randrange(len(data)):]
    for _ in range(random.randint(1,20)):
        op=random.randrange(6)
        if op==0 and data:
            data[random.randrange(len(data))]=random.randrange(256)
        elif op==1:
            pos=random.randrange(len(data)+1); data[pos:pos]=os.urandom(random.randint(1,8))
        elif op==2 and data:
            pos=random.randrange(len(data)); del data[pos:pos+random.randint(1,8)]
        elif op==3 and data:
            pos=random.randrange(len(data)); data[pos:pos]=data[max(0,pos-random.randint(1,20)):pos]
        elif op==4 and data:
            pos=random.randrange(len(data)); data[pos:pos+4]=(random.choice([0,1,2,3,4,7,15,31,127,128,255,256,65535,2**31-1])).to_bytes(4,'little',signed=False)
        elif op==5 and data:
            pos=random.randrange(len(data)); data[pos:pos+4]=(random.randrange(2**32)).to_bytes(4,'little')
    path='/tmp/mut.bin'; open(path,'wb').write(data)
    env=os.environ.copy(); env['ASAN_OPTIONS']='detect_leaks=0:abort_on_error=1'
    r=subprocess.run(['/tmp/hts_open_asan',path],stdout=subprocess.DEVNULL,stderr=subprocess.PIPE,env=env,timeout=1)
    if r.returncode not in (0,):
        err=r.stderr.decode('latin1','ignore')
        if 'ERROR: AddressSanitizer' in err:
            out=f'/workspace/poc_found_{i}.bin'; open(out,'wb').write(data)
            print('FOUND',i,out,'len',len(data),'ret',r.returncode); print(err[:4000]); sys.exit(0)
    if i%1000==0: print('iter',i,'time',time.time()-start)
print('none')
